def calc(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return (None, None)

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        val = parse_term()
        while True:
            t, _ = peek()
            if t == '+':
                advance()
                val = val + parse_term()
            elif t == '-':
                advance()
                val = val - parse_term()
            else:
                break
        return val

    def parse_term():
        val = parse_unary()
        while True:
            t, _ = peek()
            if t == '*':
                advance()
                val = val * parse_unary()
            elif t == '/':
                advance()
                rhs = parse_unary()
                val = trunc_div(val, rhs)
            else:
                break
        return val

    def parse_unary():
        t, _ = peek()
        if t == '-':
            advance()
            return -parse_unary()
        return parse_primary()

    def parse_primary():
        t, v = peek()
        if t == 'NUM':
            advance()
            return v
        elif t == '(':
            advance()
            val = parse_expr()
            t2, _ = peek()
            if t2 != ')':
                raise ValueError("Expected ')'")
            advance()
            return val
        else:
            raise ValueError(f"Unexpected token: {t}")

    def trunc_div(a, b):
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

